    for i in range(k - 1, 0, -1):
        max_solve_today = 2 * a[i]
        if n <= 0:
            break
        if n >= max_solve_today - a[i]:
            a[i] += max_solve_today - a[i]
            n -= max_solve_today - a[i]
        else:
            a[i] += n
            n = 0

    # Check if we have distributed all problems
    if n == 0:
        print("YES")
        print(*a)
    else:
